double dtw_distance(const std::vector<double>& a, const std::vector<double>& b) {
    size_t n = a.size(), m = b.size();
    const double INF = 1e100;
    std::vector<std::vector<double>> D(n + 1, std::vector<double>(m + 1, INF));
    D[0][0] = 0.0;
    for (size_t i = 1; i <= n; ++i) {
        for (size_t j = 1; j <= m; ++j) {
            double cost = std::abs(a[i - 1] - b[j - 1]);
            D[i][j] = cost + std::min({D[i - 1][j], D[i][j - 1], D[i - 1][j - 1]});
        }
    }
    return D[n][m];
}

double mean(const std::vector<double>& v) {
    double s = 0.0;
    for (double x : v) s += x;
    return s / v.size();
}

double stddev(const std::vector<double>& v) {
    double m = mean(v);
    double s = 0.0;
    for (double x : v) s += (x - m) * (x - m);
    return std::sqrt(s / v.size());
}

double median(std::vector<double> v) {
    std::sort(v.begin(), v.end());
    return v[v.size() / 2];
}

int main() {
    std::vector<std::vector<double>> days;
    days.insert(days.end(), normal_days.begin(), normal_days.end());
    days.insert(days.end(), drifted_days.begin(), drifted_days.end());
    size_t change_at = normal_days.size();

    std::vector<double> cal_means, cal_stds;
    for (const auto& d : normal_days) {
        cal_means.push_back(mean(d));
        cal_stds.push_back(stddev(d));
    }
    double mu_m = mean(cal_means);
    double sd_m = stddev(cal_means) == 0.0 ? 1e-9 : stddev(cal_means);
    double mu_s = mean(cal_stds);
    double sd_s = stddev(cal_stds) == 0.0 ? 1e-9 : stddev(cal_stds);

    std::vector<size_t> point_alarms;
    for (size_t i = 0; i < days.size(); ++i) {
        double z_mean = std::abs(mean(days[i]) - mu_m) / sd_m;
        double z_std = std::abs(stddev(days[i]) - mu_s) / sd_s;
        if (z_mean > 3.0 || z_std > 3.0) point_alarms.push_back(i);
    }

    std::vector<double> dists;
    for (const auto& d : days) dists.push_back(dtw_distance(d, reference));
    std::vector<double> cal(dists.begin(), dists.begin() + change_at);
    double med = median(cal);
    std::vector<double> absdev;
    for (double x : cal) absdev.push_back(std::abs(x - med));
    double mad = median(absdev);
    if (mad == 0.0) mad = 1e-9;
    double fence = med + 6.0 * 1.4826 * mad;

    double alpha = 0.4;
    double ewma = dists[0];
    std::vector<size_t> shape_alarms;
    for (size_t i = 0; i < dists.size(); ++i) {
        ewma = alpha * dists[i] + (1.0 - alpha) * ewma;
        if (ewma > fence) shape_alarms.push_back(i);
    }

    long first_alarm = shape_alarms.empty() ? -1 : static_cast<long>(shape_alarms[0]);
    std::cout << "point-statistic alarms on shape-drift days: ";
    for (size_t i : point_alarms) if (i >= change_at) std::cout << i << " ";
    std::cout << "\nshape alarms: first at day " << first_alarm << " (change at day " << change_at
              << ") - fence " << fence << " - calib DTW ~" << med;
    std::vector<double> drift_dists(dists.begin() + change_at, dists.end());
    std::sort(drift_dists.begin(), drift_dists.end());
    std::cout << " - drift DTW ~" << drift_dists[drift_dists.size() / 2] << "\n";

    bool point_on_drift = false;
    for (size_t i : point_alarms) if (i >= change_at) { point_on_drift = true; break; }
    assert(!point_on_drift);

    assert(!shape_alarms.empty() && change_at <= shape_alarms[0] && shape_alarms[0] <= change_at + 2);

    bool false_alarm = false;
    for (size_t i : shape_alarms) if (i < change_at) { false_alarm = true; break; }
    assert(!false_alarm);

    std::cout << "dtw_shape_drift_monitor.cpp PASS\n";
    return 0;
}
